INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES (1, "---", 2, 1, "", 0, 1, "", "アヤネ", 1);
INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES (2, "---", 1, 3, "", 6000, 0, "逆境に屈することなく、部員たちを引っ張る主将。ミート力を活かした安定感のある打撃が持ち味。", "アサヒ", 1);
INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES (3, "アドレナリン", 3, 0, "ホームランを連発すると、連発数に応じてパワーアップする", 16000, 3, "無愛想だが仲間を大切に想う気持ちは誰よりも強い男。ケンカで鍛えた腕っぷしが自慢のパワーヒッター。", "部員3", 1);
INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES (4, "ラッキー", 2, 2, "幸運のハプニングを呼び込む", 30000, 2, "みんなからの厚い信頼を集める期待の助っ人部員。実力は未知数だが幸運なハプニングを呼び込む。", "{0}", 1);
INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES (5, "", 0, 1, "", 50000, 1, "みんなの知らない極秘情報がのっているおまけページ。決して誰かに見せてはいけない。", "選手名鑑 おまけページ", 0);
INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES (6, "", 1, 1, "", 50000, 0, "", "選手名鑑 おまけページ", 0);
